134	    maintenance: 300,
135	    travelBonus: 5,
136	    desc: "实用之选",
137	  },
138	  {
139	    id: "sedan",
140	    name: "家用轿车",
141	    price: 120000,
142	    depreciation: 0.0005,
143	    maintenance: 800,
144	    travelBonus: 10,
145	    desc: "体面省油",
146	  },
147	  {
148	    id: "luxury_car",
149	    name: "豪华跑车",
150	    price: 500000,
