157	
158	function initInvestment(state) {
159	  const inv = state.investment;
160	  if (!inv) return;
161	  for (const s of INV_STOCKS)
162	    if (!inv.stockMarket[s.symbol])
163	      inv.stockMarket[s.symbol] = {
164	        price: s.basePrice * (0.85 + Math.random() * 0.3),
165	        history: [],
166	      };
167	  if (inv.btcPrice <= 0) inv.btcPrice = 200000;
168	  inv.lastTickDay = state.player.day;
169	}
170	
171	function tickInvestmentDaily(state) {
172	  const inv = state.investment;
173	  if (!inv || inv.lastTickDay >= state.player.day) return;
174	  inv.lastTickDay = state.player.day;
175	  for (const s of INV_STOCKS) {
176	    const m = inv.stockMarket[s.symbol];
177	    if (!m) continue;
178	    m.price = Math.max(
179	      0.5,
180	      m.price * (1 + s.trend + (Math.random() - 0.5) * 2 * s.volatility),
181	    );
182	    m.price = Math.round(m.price * 100) / 100;
183	    m.history.push({ day: state.player.day, price: m.price });
184	    if (m.history.length > 20) m.history.shift();
185	  }
186	  if (inv.btcPrice > 0) {
187	    inv.btcFearGreed = Math.max(
188	      5,
189	      Math.min(95, (inv.btcFearGreed || 50) + (Math.random() - 0.5) * 10),
190	    );
191	    inv.btcPrice = Math.max(
192	      1000,
193	      Math.round(
194	        inv.btcPrice *
195	          (1 +
196	            (Math.random() - 0.5) * 0.08 +
197	            ((inv.btcFearGreed - 50) / 50) * 0.02),
198	      ),
199	    );
200	    if (state.player.day - inv.btcHalvingDay > 1460) {
201	      inv.btcHalvingDay = state.player.day;
202	      inv.btcFearGreed = Math.min(95, inv.btcFearGreed + 20);
203	      StateManager.addMessage("比特币减半事件！", "event");
204	    }
205	  }
206	  for (const p of inv.properties || []) {
207	    p.currentPrice = Math.round(
208	      (p.currentPrice || p.buyPrice) *
209	        (1 + p.appreciation + (Math.random() - 0.5) * 0.002),
210	    );
211	    if (state.player.day % 30 === 0) state.resources.cash += p.rent || 0;
212	  }
213	  for (const c of inv.cars || []) {
214	    c.currentPrice = Math.round(
215	      (c.currentPrice || c.buyPrice) * (1 - c.depreciation),
216	    );
217	    if (state.player.day % 30 === 0 && state.resources.cash >= c.maintenance)
218	      state.resources.cash -= c.maintenance;
219	  }
220	}
221	
222	function buyInvStock(symbol, shares) {
223	  const state = StateManager.getState();
224	  const inv = state.investment;
225	  const m = inv.stockMarket[symbol];
226	  if (!m) return;
227	  const cost = Math.round(m.price * shares * 100) / 100;
228	  if (state.resources.cash < cost) {
229	    StateManager.addMessage("现金不足", "danger");
230	    return;
231	  }
232	  state.resources.cash -= cost;
233	  const h = inv.stockHoldings.find((s) => s.symbol === symbol);
234	  if (h) {
235	    const total = h.shares + shares;
236	    h.avgPrice =
237	      Math.round(((h.avgPrice * h.shares + cost) / total) * 100) / 100;
238	    h.shares = total;
239	  } else inv.stockHoldings.push({ symbol, shares, avgPrice: m.price });
240	  StateManager.addMessage("买入 " + symbol + " " + shares + "股", "success");
241	}
242	
243	function sellInvStock(symbol, shares) {
244	  const state = StateManager.getState();
245	  const inv = state.investment;
246	  const h = inv.stockHoldings.find((s) => s.symbol === symbol);
247	  if (!h || h.shares < shares) {
248	    StateManager.addMessage("持仓不足", "danger");
249	    return;
250	  }
251	  const m = inv.stockMarket[symbol];
252	  const revenue = Math.round(m.price * shares * 100) / 100;
253	  state.resources.cash += revenue;
254	  h.shares -= shares;
255	  if (h.shares <= 0)
256	    inv.stockHoldings = inv.stockHoldings.filter((s) => s.symbol !== symbol);
257	  StateManager.addMessage("卖出 " + symbol + " " + shares + "股", "success");
258	}
259	
260	function buyBtc(amount) {
261	  const state = StateManager.getState();
262	  const inv = state.investment;
263	  const cost = Math.round(inv.btcPrice * amount * 100) / 100;
264	  if (state.resources.cash < cost) {
265	    StateManager.addMessage("现金不足", "danger");
266	    return;
267	  }
268	  state.resources.cash -= cost;
269	  inv.btcHoldings = Math.round((inv.btcHoldings + amount) * 10000) / 10000;
270	  StateManager.addMessage("买入 " + amount + " BTC", "success");
271	}
272	
273	function sellBtc(amount) {
274	  const state = StateManager.getState();
275	  const inv = state.investment;
276	  if (inv.btcHoldings < amount) {
277	    StateManager.addMessage("持仓不足", "danger");
278	    return;
279	  }
280	  state.resources.cash += Math.round(inv.btcPrice * amount * 100) / 100;
281	  inv.btcHoldings = Math.round((inv.btcHoldings - amount) * 10000) / 10000;
282	  StateManager.addMessage("卖出 " + amount + " BTC", "success");
283	}
284	
285	function buyProperty(propId) {
286	  const state = StateManager.getState();
287	  const inv = state.investment;
288	  const prop = PROPERTIES.find((p) => p.id === propId);
289	  if (!prop) return;
290	  if (state.resources.cash < prop.price) {
291	    StateManager.addMessage("现金不足", "danger");
292	    return;
293	  }
294	  state.resources.cash -= prop.price;
295	  inv.properties.push({
296	    ...prop,
297	    buyPrice: prop.price,
298	    currentPrice: prop.price,
299	    buyDay: state.player.day,
300	  });
301	  StateManager.addMessage("购入" + prop.name, "success");
302	}
303	
304	function sellProperty(propId) {
305	  const state = StateManager.getState();
306	  const inv = state.investment;
307	  const idx = inv.properties.findIndex((p) => p.id === propId);
308	  if (idx < 0) return;
309	  const prop = inv.properties[idx];
310	  const net = prop.currentPrice - Math.round(prop.currentPrice * 0.05);
311	  state.resources.cash += net;
312	  inv.properties.splice(idx, 1);
313	  StateManager.addMessage("出售" + prop.name + " 到手" + net, "success");
314	}
315	
316	function buyCar(carId) {
317	  const state = StateManager.getState();
318	  const inv = state.investment;
319	  const car = CAR_TYPES.find((c) => c.id === carId);
320	  if (!car) return;
321	  if (state.resources.cash < car.price) {
322	    StateManager.addMessage("现金不足", "danger");
323	    return;
324	  }
325	  state.resources.cash -= car.price;
326	  inv.cars.push({
327	    ...car,
328	    buyPrice: car.price,
329	    currentPrice: car.price,
330	    buyDay: state.player.day,
331	  });
332	  state.player.maxActionPoints =
333	    (state.player.maxActionPoints || 100) + car.travelBonus;
334	  state.player.actionPoints = Math.min(
335	    state.player.maxActionPoints,
336	    state.player.actionPoints + car.travelBonus,
337	  );
338	  StateManager.addMessage(
339	    "购入" + car.name + " 行动力上限+" + car.travelBonus,
340	    "success",
341	  );
342	}
343	
344	function renderInvestmentTab(state, parent) {
345	  const inv = state.investment;
346	  if (!inv) {
347	    parent.innerHTML = "<p>投资系统加载中...</p>";
348	    return;
349	  }
350	  if (
351	    Object.keys(inv.stockMarket).length === 0 &&
352	    typeof initInvestment === "function"
353	  )
354	    initInvestment(state);
355	
356	  const stockVal = inv.stockHoldings.reduce(
357	    (s, h) => s + (inv.stockMarket[h.symbol]?.price || 0) * h.shares,
358	    0,
359	  );
360	  const btcVal = inv.btcPrice * inv.btcHoldings;
361	  const propVal = (inv.properties || []).reduce(
362	    (s, p) => s + (p.currentPrice || p.buyPrice),
363	    0,
364	  );
365	  const carVal = (inv.cars || []).reduce(
366	    (s, c) => s + (c.currentPrice || c.buyPrice),
367	    0,
368	  );
369	  const totalInv = stockVal + btcVal + propVal + carVal;
370	
371	  parent.innerHTML = "";
372	  const cont = document.createElement("div");
373	  cont.innerHTML =
374	    '<h3>投资中心 <span style="font-size:12px;color:var(--accent);">总资产 ' +
375	    totalInv.toLocaleString() +
376	    "</span></h3>" +
377	    '<div style="display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px;">' +
378	    '<div class="action-card" style="flex:1;min-width:100px;text-align:center;padding:8px;"><div style="font-size:10px;color:var(--text-muted);">股票</div><strong>' +
379	    stockVal.toLocaleString() +
380	    "</strong></div>" +
381	    '<div class="action-card" style="flex:1;min-width:100px;text-align:center;padding:8px;"><div style="font-size:10px;color:var(--text-muted);">比特币</div><strong>' +
382	    btcVal.toLocaleString() +
383	    "</strong></div>" +
384	    '<div class="action-card" style="flex:1;min-width:100px;text-align:center;padding:8px;"><div style="font-size:10px;color:var(--text-muted);">房产</div><strong>' +
385	    propVal.toLocaleString() +
386	    "</strong></div>" +
387	    '<div class="action-card" style="flex:1;min-width:100px;text-align:center;padding:8px;"><div style="font-size:10px;color:var(--text-muted);">汽车</div><strong>' +
388	    carVal.toLocaleString() +
389	    "</strong></div>" +
390	    "</div>" +
391	    '<div style="display:flex;gap:4px;margin-bottom:8px;">' +
392	    '<button class="btn btn-sm sub-tab active" data-stab="stocks">股票</button>' +
393	    '<button class="btn btn-sm sub-tab" data-stab="btc">比特币</button>' +
394	    '<button class="btn btn-sm sub-tab" data-stab="re">房产</button>' +
395	    '<button class="btn btn-sm sub-tab" data-stab="car">汽车</button>' +
396	    '</div><div id="inv-sub-area"></div>';
397	  parent.appendChild(cont);
398	
399	  const renderSub = function (stab) {
400	    const area = document.getElementById("inv-sub-area");
401	    if (!area) return;
402	    area.innerHTML = "";
403	    if (stab === "stocks") {
404	      const grid = document.createElement("div");
405	      grid.className = "action-cards";
406	      grid.style.gridTemplateColumns = "repeat(auto-fill,minmax(220px,1fr))";
407	      for (const s of INV_STOCKS) {
408	        const m = inv.stockMarket[s.symbol];
409	        if (!m) continue;
410	        const h = inv.stockHoldings.find(function (h) {
411	          return h.symbol === s.symbol;
412	        });
413	        const chg =
414	          m.history.length >= 2
415	            ? m.price - m.history[m.history.length - 2].price
416	            : 0;
417	        const clr = chg >= 0 ? "var(--success)" : "var(--danger)";
418	        const card = document.createElement("div");
419	        card.className = "action-card";
420	        card.style.borderLeft = "3px solid " + clr;
421	        card.innerHTML =
422	          '<div style="display:flex;justify-content:space-between;"><strong>' +
423	          s.symbol +
424	          " " +
425	          s.name +
426	          '</strong><span style="color:' +
427	          clr +
428	          '">' +
429	          m.price.toFixed(2) +
430	          "</span></div>" +
431	          '<div style="font-size:10px;color:var(--text-muted);">' +
432	          s.industry +
433	          " | " +
434	          s.desc +
435	          "</div>" +
436	          (h
437	            ? '<div style="font-size:10px;margin:4px 0;">持仓' +
438	              h.shares +
439	              "股 均价" +
440	              h.avgPrice.toFixed(2) +
441	              ' 盈亏<span style="color:' +
442	              clr +
443	              '">' +
444	              Math.round((m.price - h.avgPrice) * h.shares) +
445	              "</span></div>"
446	            : "") +
447	          '<div style="display:flex;gap:3px;margin-top:4px;">' +
448	          '<button class="btn btn-sm btn-success ibuy" data-s="' +
449	          s.symbol +
450	          '" data-q="10">买10</button>' +
451	          '<button class="btn btn-sm btn-success ibuy" data-s="' +
452	          s.symbol +
453	          '" data-q="100">买100</button>' +
454	          '<button class="btn btn-sm btn-danger isell" data-s="' +
455	          s.symbol +
456	          '" data-q="10">卖10</button>' +
457	          '<button class="btn btn-sm btn-danger isell" data-s="' +
458	          s.symbol +
459	          '" data-q="' +
460	          (h ? h.shares : 0) +
461	          '">全卖</button></div>';
462	        grid.appendChild(card);
463	      }
464	      area.appendChild(grid);
465	      setTimeout(function () {
466	        area.querySelectorAll(".ibuy").forEach(function (b) {
467	          b.onclick = function () {
468	            buyInvStock(b.dataset.s, parseInt(b.dataset.q));
469	            renderInvestmentTab(state, parent);
470	          };
471	        });
472	        area.querySelectorAll(".isell").forEach(function (b) {
473	          b.onclick = function () {
474	            sellInvStock(b.dataset.s, parseInt(b.dataset.q));
475	            renderInvestmentTab(state, parent);
476	          };
477	        });
478	      }, 0);
479	    }
480	  };
481	
482	  setTimeout(function () {
483	    renderSub("stocks");
484	    cont.querySelectorAll(".sub-tab").forEach(function (btn) {
485	      btn.addEventListener("click", function () {
486	        cont.querySelectorAll(".sub-tab").forEach(function (b) {
487	          b.classList.remove("active");
488	        });
489	        btn.classList.add("active");
490	        renderSub(btn.dataset.stab);
491	      });
492	    });
493	  }, 0);
494	}
