244	// ============================================================
245	//  Canvas 涨跌曲线图
246	// ============================================================
247	function drawPriceChart(canvasId, priceData, color) {
248	  var canvas = typeof canvasId === "string" ? document.getElementById(canvasId) : canvasId;
249	  if (!canvas) return;
250	  var ctx = canvas.getContext("2d");
251	  var W = canvas.width, H = canvas.height;
252	  ctx.clearRect(0, 0, W, H);
253	
254	  var data = (priceData || []).slice(-20);
255	  if (data.length < 2) {
256	    ctx.fillStyle = "#999";
257	    ctx.font = "12px sans-serif";
258	    ctx.textAlign = "center";
259	    ctx.fillText("等待数据...", W / 2, H / 2);
260	    return;
261	  }
262	
263	  var prices = [];
264	  for (var i = 0; i < data.length; i++) prices.push(data[i].price);
265	
266	  var minP = prices[0], maxP = prices[0];
267	  for (var i = 1; i < prices.length; i++) {
268	    if (prices[i] < minP) minP = prices[i];
269	    if (prices[i] > maxP) maxP = prices[i];
270	  }
271	  var range = maxP - minP;
272	  if (range === 0) range = minP * 0.1 || 1;
273	  var padT = 4, padB = 4, padL = 4, padR = 4;
274	  var chartW = W - padL - padR;
275	  var chartH = H - padT - padB;
276	
277	  // 网格线
278	  if (ctx.strokeStyle) {
279	    ctx.strokeStyle = "rgba(255,255,255,0.06)";
280	    ctx.lineWidth = 0.5;
281	    for (var i = 0; i < 4; i++) {
282	      var y = padT + (chartH / 4) * i;
283	      ctx.beginPath();
284	      ctx.moveTo(padL, y);
285	      ctx.lineTo(W - padR, y);
286	      ctx.stroke();
287	    }
288	  }
289	
290	  // 折线
291	  var lineColor = color || "#4fc3f7";
292	  ctx.beginPath();
293	  ctx.strokeStyle = lineColor;
294	  ctx.lineWidth = 1.5;
295	  var firstX, firstY, lastX, lastY;
296	  for (var i = 0; i < prices.length; i++) {
297	    var x = padL + (i / (prices.length - 1)) * chartW;
298	    var y = padT + chartH - ((prices[i] - minP) / range) * chartH;
299	    if (i === 0) {
300	      ctx.moveTo(x, y);
301	      firstX = x; firstY = y;
302	    } else {
303	      ctx.lineTo(x, y);
304	    }
305	    if (i === prices.length - 1) { lastX = x; lastY = y; }
306	  }
307	  ctx.stroke();
308	
309	  // 渐变填充
310	  var grad = ctx.createLinearGradient(0, padT, 0, H - padB);
311	  grad.addColorStop(0, lineColor + "30");
312	  grad.addColorStop(1, lineColor + "02");
313	  ctx.fillStyle = grad;
314	  ctx.beginPath();
315	  ctx.moveTo(firstX, H - padB);
316	  for (var i = 0; i < prices.length; i++) {
317	    var x = padL + (i / (prices.length - 1)) * chartW;
318	    var y = padT + chartH - ((prices[i] - minP) / range) * chartH;
319	    if (i === 0) ctx.lineTo(x, y);
320	    else ctx.lineTo(x, y);
321	  }
322	  ctx.lineTo(lastX, H - padB);
323	  ctx.closePath();
324	  ctx.fill();
325	
326	  // 当前价格
327	  var lastPrice = prices[prices.length - 1];
328	  var prevPrice = prices.length >= 2 ? prices[prices.length - 2] : lastPrice;
329	  var chg = lastPrice - prevPrice;
330	  var chgPct = prevPrice !== 0 ? ((chg / prevPrice) * 100).toFixed(2) : "0.00";
331	  var chgText = (chg >= 0 ? "+" : "") + chgPct + "%";
332	
333	  ctx.fillStyle = lineColor;
334	  ctx.font = "bold 11px sans-serif";
335	  ctx.textAlign = "left";
336	  ctx.fillText(lastPrice.toFixed(2), padL + 2, padT + 10);
337	
338	  ctx.fillStyle = chg >= 0 ? "#4caf50" : "#f44336";
339	  ctx.font = "9px sans-serif";
340	  ctx.fillText(chgText, padL + 2, padT + 21);
341	}
