712	// ---- 子tab渲染：房产 ----
713	function renderProperties(area, inv) {
714	  var list = inv.properties || [];
715	  if (list.length === 0) {
716	    area.innerHTML = '<p style="color:var(--text-muted);font-size:12px;">尚未购入房产，前往商城购买。</p>';
717	    return;
718	  }
719	
720	  var div = document.createElement("div");
721	  div.className = "action-cards";
722	
723	  for (var i = 0; i < list.length; i++) {
724	    var p = list[i];
725	    var cur = p.currentPrice || p.buyPrice;
726	    var buyP = p.buyPrice;
727	    var diff = cur - buyP;
728	    var pct = ((diff / buyP) * 100).toFixed(1);
729	    var clr = diff >= 0 ? "var(--success)" : "var(--danger)";
730	
731	    var card = document.createElement("div");
732	    card.className = "action-card";
733	    card.style.borderLeft = "3px solid " + clr;
734	    card.innerHTML =
735	      '<div style="display:flex;justify-content:space-between;">' +
736	        '<strong>' + p.name + '</strong>' +
737	        '<span style="color:' + clr + '">' + (diff >= 0 ? "+" : "") + pct + '%</span>' +
738	      '</div>' +
739	      '<div style="font-size:10px;color:var(--text-muted);">' + (p.type || "") + '</div>' +
740	      '<div style="font-size:11px;margin:4px 0;">' +
741	        '买入价: ' + buyP.toLocaleString() +
742	        ' | 当前估值: ' + cur.toLocaleString() +
743	      '</div>' +
744	      '<div style="display:flex;gap:3px;margin-top:4px;">' +
745	        '<button class="btn btn-sm btn-danger sell-prop" data-id="' + p.id + '">出售</button>' +
746	      '</div>' +
747	      '<div style="margin-top:4px;height:6px;background:rgba(0,0,0,0.1);border-radius:3px;overflow:hidden;">' +
748	        '<div style="height:100%;width:' + Math.min(100, Math.max(0, (cur / buyP) * 100)) + '%;background:' + clr + ';border-radius:3px;"></div>' +
749	      '</div>';
750	    div.appendChild(card);
751	  }
752	
753	  area.appendChild(div);
754	
755	  setTimeout(function() {
756	    area.querySelectorAll(".sell-prop").forEach(function(b) {
757	      b.onclick = function() {
758	        sellProperty(this.dataset.id);
759	        renderInvestmentTab(state, parent);
760	      };
761	    });
762	  }, 0);
763	}
